create or replace function public.directory(p jsonb)returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(x),'[]')from(select pr.id,pr.display_name,pr.designation,pr.subjects,pr.classes,pr.approved_fields,pr.published_at from public.teacher_profiles pr where private.profile_visible(pr.id)and(coalesce(p->>'q','')=''or to_tsvector('simple',pr.display_name||' '||pr.designation)@@plainto_tsquery('simple',p->>'q')or pr.display_name ilike '%'||replace(replace(replace(p->>'q','\','\\'),'%','\%'),'_','\_')||'%')and(coalesce(p->>'subject','')=''or p->>'subject'=any(pr.subjects))and(coalesce(p->>'className','')=''or p->>'className'=any(pr.classes))order by case when lower(pr.display_name)=lower(p->>'q')then 0 when lower(pr.display_name)like lower(p->>'q')||'%'then 1 else 2 end,lower(pr.display_name),pr.id limit least(coalesce((p->>'limit')::int,25),100)offset greatest(coalesce((p->>'offset')::int,0),0))x$$;
create function public.query_archive(p jsonb)returns jsonb language plpgsql stable security definer set search_path='' as $$begin perform private.learning_access();if private.role()<>'student'then raise exception 'FORBIDDEN'using errcode='42501';end if;return(select coalesce(jsonb_agg(x),'[]')from(select id,teacher_id,subject,topic,state,cycle,created_at from public.queries q where student_id=auth.uid()and school_id=private.school()and(p->>'state'is null or state=p->>'state')and(p->>'teacherId'is null or teacher_id=(p->>'teacherId')::uuid)and(p->>'subject'is null or subject=p->>'subject')and(p->>'q'is null or topic ilike '%'||replace(replace(p->>'q','%','\%'),'_','\_')||'%')and(p->>'from'is null or created_at>=(p->>'from')::timestamptz)and(p->>'to'is null or created_at<(p->>'to')::timestamptz)order by created_at desc,id limit least(coalesce((p->>'limit')::int,25),100)offset greatest(coalesce((p->>'offset')::int,0),0))x);end$$;
revoke execute on function public.query_archive(jsonb)from public,anon,authenticated;grant execute on function public.query_archive(jsonb)to authenticated;
